import{_ as n,C as s,o as e,c as d,j as i,a as o,E as l,a2 as t}from"./chunks/framework.C21TwvGF.js";const W=JSON.parse(`{"title":"5-dars (Mentor). Internet, brauzerlar va elektron pochta bilan ishlash","description":"","frontmatter":{"title":"5-dars (Mentor). Internet, brauzerlar va elektron pochta bilan ishlash","layout":"doc","sidebar":false,"aside":false,"outline":false,"kind":"mentor_dars","dars":{"sinf":{"name":"8-sinf (Foundation)","link":"/mentor/8-sinf-cs/"},"week":{"n":2,"link":"/mentor/8-sinf-cs/hafta-02/"},"g":5,"title":"Internet, brauzerlar va elektron pochta bilan ishlash","lead":"Global tarmoq sirlari, brauzerlar anatomiyasi, Google'da professional qidiruv usullari hamda elektron pochtada xavfsiz va samarali ishlash madaniyati.","slide":"/slaydlar/8-sinf-cs/hafta-02/dars-2.html","test":"/slaydlar/8-sinf-cs/hafta-02/dars-2-test.html","student_link":"/8-sinf-cs/hafta-02/dars-2","tabs":[{"g":4,"link":"/mentor/8-sinf-cs/hafta-02/dars-1","current":false},{"g":5,"link":"/mentor/8-sinf-cs/hafta-02/dars-2","current":true},{"g":6,"link":"/mentor/8-sinf-cs/hafta-02/dars-3","current":false}],"prev":{"g":4,"title":"Kompyuterning asosiy va qo'shimcha qurilmalari","link":"/mentor/8-sinf-cs/hafta-02/dars-1"},"next":{"g":6,"title":"Kompyuter xavfsizligi va antivirus dasturlari","link":"/mentor/8-sinf-cs/hafta-02/dars-3"}}},"headers":[],"relativePath":"mentor/8-sinf-cs/hafta-02/dars-2.md","filePath":"mentor/8-sinf-cs/hafta-02/dars-2.md"}`),h={name:"mentor/8-sinf-cs/hafta-02/dars-2.md"},u={class:"blk"},c={id:"_1-dars-rejasi",tabindex:"-1"},m={class:"blk"},g={id:"_2-dars-konspekti",tabindex:"-1"},b={class:"blk"},y={id:"_3-amaliy-topshiriqlar-va-yechimlari",tabindex:"-1"},k={class:"blk"},p={id:"_4-tezkor-nazorat-savollari-javoblari-bilan",tabindex:"-1"};function v(f,a,q,z,x,_){const r=s("Icon");return e(),d("div",null,[a[12]||(a[12]=i("p",null,[i("strong",null,"Hafta:"),o(" 2 · "),i("strong",null,"Davomiyligi:"),o(" 80 daqiqa · "),i("strong",null,"Turi:"),o(" nazariya + amaliy mashg'ulot · "),i("strong",null,"I-bob"),o(", 5-dars")],-1)),i("div",u,[i("h2",c,[l(r,{name:"file-text"}),a[0]||(a[0]=o(" 1. Dars rejasi ",-1)),a[1]||(a[1]=i("a",{class:"header-anchor",href:"#_1-dars-rejasi","aria-label":'Permalink to "<Icon name="file-text" /> 1. Dars rejasi"'},"​",-1))]),a[2]||(a[2]=t('<p><strong>Maqsad:</strong> o&#39;quvchilarga Internet va World Wide Web (WWW) tushunchalari, zamonaviy brauzerlarning ishlash mexanizmlari, qidiruv tizimlarida samarali qidiruv operatorlaridan foydalanish ko&#39;nikmalari hamda elektron pochta (Email) tizimida xat yozish, formatlash, fayllarni to&#39;g&#39;ri biriktirish va kibergigiyena qoidalarini amaliy o&#39;rgatish.</p><p><strong>Kutiladigan natija:</strong></p><ul><li>Internet va veb-sayt (WWW) tushunchalari o&#39;rtasidagi farqni tushuntira oladi.</li><li>Mashhur brauzerlar (Chrome, Edge, Firefox, Safari) interfeysini, xatcho&#39;plar (bookmarks), tarix (history), kesh (cache) va inkognito rejimidan foydalanishni biladi.</li><li>Qidiruv operatorlari (<code>&quot;&quot;</code>, <code>-</code>, <code>site:</code>, <code>filetype:</code>) yordamida aniq axborotni bir necha soniyada topadi.</li><li>Elektron pochta manzili strukturasi, xat yozishdagi maydonlar (<code>To</code>, <code>Cc</code>, <code>Bcc</code>, <code>Subject</code>, <code>Body</code>, <code>Attachment</code>) vazifasini farqlaydi va professional xat yoza oladi.</li><li>Fishing (phishing), spam va shubhali fayllardan himoyalanishning asosiy xavfsizlik qoidalariga rioya qiladi.</li></ul><table tabindex="0"><thead><tr><th>Vaqt</th><th>Bosqich</th><th>Mazmun</th></tr></thead><tbody><tr><td>0–10 daq</td><td>Takrorlash va muammo qo&#39;yish</td><td>O&#39;tgan darsni takrorlash (kompyuter qurilmalari va portlar). Muammoli savol: «Internet va brauzer bitta narsami? Google qidiruvida kerakli natijani qanday qilib 1-sahifadayoq topish mumkin?»</td></tr><tr><td>10–30 daq</td><td>Yangi mavzu: Nazariya</td><td>Internet tushunchasi, brauzerlar ishlashi, qidiruv operatorlari, elektron pochta anatomiyasi va xavfsizlik</td></tr><tr><td>30–35 daq</td><td>Tanaffus</td><td>Ko&#39;z va tana mashqlari</td></tr><tr><td>35–65 daq</td><td>Amaliy mashg&#39;ulot</td><td>Brauzer sozlamalarini o&#39;rganish, Google qidiruv operatorlarini sinash, elektron pochta xatini tayyorlash (Cc/Bcc va birikma bilan)</td></tr><tr><td>65–75 daq</td><td>Tezkor nazorat</td><td>5 ta tezkor savol-javob va interaktiv tahlil</td></tr><tr><td>75–80 daq</td><td>Xulosa va uyga vazifa</td><td>Muhim fikrlarni jamlash va topshiriqlarni belgilash</td></tr></tbody></table><hr>',5))]),i("div",m,[i("h2",g,[l(r,{name:"file-text"}),a[3]||(a[3]=o(" 2. Dars konspekti ",-1)),a[4]||(a[4]=i("a",{class:"header-anchor",href:"#_2-dars-konspekti","aria-label":'Permalink to "<Icon name="file-text" /> 2. Dars konspekti"'},"​",-1))]),a[5]||(a[5]=t('<h3 id="_2-1-internet-va-world-wide-web-www-tushunchasi" tabindex="-1">2.1. Internet va World Wide Web (WWW) tushunchasi <a class="header-anchor" href="#_2-1-internet-va-world-wide-web-www-tushunchasi" aria-label="Permalink to &quot;2.1. Internet va World Wide Web (WWW) tushunchasi&quot;">​</a></h3><ul><li><strong>Internet (International Network):</strong> Butun dunyo bo&#39;ylab millionlab kompyuterlar, serverlar va mobil qurilmalarni o&#39;zaro bog&#39;lagan global axborot tarmog&#39;idir. U jismoniy infratuzilma (kabellar, optik tolalar, sun&#39;iy yo&#39;ldoshlar, marshrutizatorlar) hisoblanadi.</li><li><strong>World Wide Web (WWW / Butunjahon o&#39;rgimchak to&#39;ri):</strong> Internet tarmog&#39;ida joylashgan, gipermatnlar (HTML) va multimedia fayllaridan iborat veb-sahifalar va saytlar tizimidir. Internet — bu yo&#39;llar tarmog&#39;i bo&#39;lsa, WWW — bu yo&#39;lda harakatlanayotgan mashinalar va yetkazilayotgan yuklardir.</li><li><strong>Mijoz-Server modeli (Client-Server):</strong><ul><li><strong>Mijoz (Client):</strong> Ma&#39;lumot so&#39;rovchi qurilma (masalan, sizning kompyuteringiz yoki brauzeringiz).</li><li><strong>Server:</strong> Ma&#39;lumotlarni saqlovchi va so&#39;rovga binoan ularni qaytaruvchi kuchli kompyuter.</li></ul></li></ul><h3 id="_2-2-veb-brauzerlar-va-ularning-imkoniyatlari" tabindex="-1">2.2. Veb-brauzerlar va ularning imkoniyatlari <a class="header-anchor" href="#_2-2-veb-brauzerlar-va-ularning-imkoniyatlari" aria-label="Permalink to &quot;2.2. Veb-brauzerlar va ularning imkoniyatlari&quot;">​</a></h3><p>Brauzer (Web Browser) — internetdagi veb-sayt kodlarini (HTML, CSS, JavaScript) o&#39;qib, ularni insonga tushunarli grafik ko&#39;rinishga keltirib beruvchi dasturdir.</p><p>Eng mashhur brauzerlar:</p><ol><li><strong>Google Chrome:</strong> Dunyoda eng keng tarqalgan va tezkor brauzer (Blink dvigateli).</li><li><strong>Microsoft Edge:</strong> Windows tizimiga o&#39;rnatilgan, Chromium asosidagi brauzer.</li><li><strong>Mozilla Firefox:</strong> Ochiq manbali, shaxsiy maxfiylikka katta e&#39;tibor beruvchi brauzer.</li><li><strong>Apple Safari:</strong> Apple qurilmalari (macOS, iOS) uchun optimallashtirilgan brauzer.</li></ol><p>Brauzerning asosiy elementlari va vositalari:</p><ul><li><strong>Tablar (Yorliqlar):</strong> Bir oynada bir vaqtning o&#39;zida bir nechta sahifani ochish (<code>Ctrl+T</code> — yangi tab, <code>Ctrl+W</code> — tabni yopish, <code>Ctrl+Shift+T</code> — yopilgan tabni qayta ochish).</li><li><strong>Xatcho&#39;plar (Bookmarks):</strong> Muhim va tez-tez kiriladigan saytlarni bir tugma bilan saqlab qo&#39;yish (<code>Ctrl+D</code>).</li><li><strong>Ko&#39;rish tarixi (History):</strong> Avval kirilgan sahifalar ro&#39;yxati (<code>Ctrl+H</code>).</li><li><strong>Inkognito / Maxfiy rejim (<code>Ctrl+Shift+N</code>):</strong> Bu rejimda brauzer kirilgan saytlar tarixini, qidiruv so&#39;rovlarini va cookie fayllarini xotirada saqlab qolmaydi.</li><li><strong>Kesh (Cache) va Kukilar (Cookies):</strong><ul><li><em>Kesh:</em> Sayt tez yuklanishi uchun kompyuterga saqlab olinadigan rasmlar va fayllar.</li><li><em>Kukilar:</em> Foydalanuvchi identifikatori, sayt sozlamalari yoki savatcha ma&#39;lumotlarini eslab qoluvchi kichik matnli fayllar.</li></ul></li></ul><h3 id="_2-3-qidiruv-tizimlari-va-professional-qidiruv-operatorlari" tabindex="-1">2.3. Qidiruv tizimlari va professional qidiruv operatorlari <a class="header-anchor" href="#_2-3-qidiruv-tizimlari-va-professional-qidiruv-operatorlari" aria-label="Permalink to &quot;2.3. Qidiruv tizimlari va professional qidiruv operatorlari&quot;">​</a></h3><p>Qidiruv tizimi (Search Engine) — internetdagi milliardlab sahifalar orasidan kerakli ma&#39;lumotni kalit so&#39;zlar bo&#39;yicha topib beruvchi maxsus xizmat (Google, Yandex, Bing).</p><p>Google qidiruvini professional darajaga ko&#39;taruvchi operatorlar:</p><ol><li><code>&quot;&quot;</code> (Iqtibos): Aniq so&#39;z birikmasini aynan qidirish. <ul><li>Misol: <code>&quot;Muhammad al-Xorazmiy vorislari&quot;</code></li></ul></li><li><code>-</code> (Minus / Istisno): Natijalar ichidan muayyan so&#39;zni olib tashlash. <ul><li>Misol: <code>jaguar mashina -hayvon</code></li></ul></li><li><code>site:</code> Faqat ma&#39;lum bir sayt yoki domendan qidirish. <ul><li>Misol: <code>python darslari site:edu.uz</code></li></ul></li><li><code>filetype:</code> Faqat belgilangan formatdagi fayllarni topish (pdf, docx, pptx). <ul><li>Misol: <code>computer science foundation filetype:pdf</code></li></ul></li><li><code>OR</code> (Yoki): Bir vaqtda bir nechta variantdan birini qidirish. <ul><li>Misol: <code>noutbuk Acer OR Asus</code></li></ul></li><li><code>*</code> (Yulduzcha / Wildcard): Eslab qolinmagan so&#39;z o&#39;rnida joy to&#39;ldiruvchi. <ul><li>Misol: <code>bir * ikki bo&#39;lmaydi</code></li></ul></li></ol><h3 id="_2-4-elektron-pochta-email-bilan-ishlash" tabindex="-1">2.4. Elektron pochta (Email) bilan ishlash <a class="header-anchor" href="#_2-4-elektron-pochta-email-bilan-ishlash" aria-label="Permalink to &quot;2.4. Elektron pochta (Email) bilan ishlash&quot;">​</a></h3><p>Elektron pochta (Electronic Mail) — internet orqali xat, hujjat va fayllarni tezkor almashish tizimi.</p><p>Pochta manzili tuzilishi: <code>foydalanuvchi_nomi@pochta_serveri.domen</code></p><ul><li>Masalan: <code>sherzod.alimov@gmail.com</code> (<code>@</code> belgisi — «kuchukcha» yoki «at» deb ataladi).</li></ul><p>Xat yuborish oynasining asosiy maydonlari:</p><ul><li><strong>To (Kimga):</strong> Xatning asosiy qabul qiluvchi shaxsining manzili.</li><li><strong>Cc (Carbon Copy / Nusxa):</strong> Xatdan xabardor bo&#39;lishi kerak bo&#39;lgan ikkinchi darajali qabul qiluvchilar (barcha oluvchilar bu manzilni ko&#39;ra oladi).</li><li><strong>Bcc (Blind Carbon Copy / Yashirin nusxa):</strong> Xat nusxasi yuboriladi, lekin asosiy qabul qiluvchilar bu manzilga xat ketganini ko&#39;ra olmaydi (maxfiylik uchun juda muhim).</li><li><strong>Subject (Mavzu):</strong> Xatning qisqa mazmuni (1 qator). Bo&#39;sh qoldirish odobsizlik hisoblanadi!</li><li><strong>Body (Xat matni):</strong> Xatning asosiy matni: salomlashish, murojaat maqsadi, xulosa va imzo.</li><li><strong>Attachment (Biriktirilgan fayl):</strong> Qisqich (paperclip) belgisi orqali xatga rasm, PDF, Word yoki arxiv fayl biriktirish. Ko&#39;p pochta xizmatlarida (Gmail) maksimal hajm 25 MB.</li></ul><h3 id="_2-5-internet-va-elektron-pochtada-xavfsizlik-qoidalari" tabindex="-1">2.5. Internet va elektron pochtada xavfsizlik qoidalari <a class="header-anchor" href="#_2-5-internet-va-elektron-pochtada-xavfsizlik-qoidalari" aria-label="Permalink to &quot;2.5. Internet va elektron pochtada xavfsizlik qoidalari&quot;">​</a></h3><ol><li><strong>Fishing (Phishing) xatlar:</strong> Bank yoki taniqli kompaniya nomidan soxta xat yuborib, login va parolni o&#39;g&#39;irlashga urinish. Hech qachon shubhali xatdagi havolaga kirmang!</li><li><strong>Spam (Keraksiz reklama xatlari):</strong> Ommaviy jo&#39;natiladigan keraksiz xabarlar. Ularni ochmasdan o&#39;chirish yoki «Spam»ga belgilash lozim.</li><li><strong>Shubhali birikmalar (Attachments):</strong> <code>.exe</code>, <code>.bat</code>, <code>.vbs</code>, <code>.scr</code> yoki shubhali arxivli fayllarni HECH QACHON ochmang — ular kompyuterga virus yuqtiradi.</li><li><strong>Jamoat Wi-Fi tarmoqlarida ehtiyotkorlik:</strong> Parolsiz ochiq Wi-Fi nuqtalarida shaxsiy pochtaga yoki bank kartasi ma&#39;lumotlariga kirmaslik tavsiya etiladi.</li></ol><hr>',21))]),i("div",b,[i("h2",y,[l(r,{name:"file-text"}),a[6]||(a[6]=o(" 3. Amaliy topshiriqlar va yechimlari ",-1)),a[7]||(a[7]=i("a",{class:"header-anchor",href:"#_3-amaliy-topshiriqlar-va-yechimlari","aria-label":'Permalink to "<Icon name="file-text" /> 3. Amaliy topshiriqlar va yechimlari"'},"​",-1))]),a[8]||(a[8]=t(`<h3 id="_1-topshiriq-brauzer-tezkor-tugmalari-va-inkognito-rejim" tabindex="-1">1-topshiriq. Brauzer tezkor tugmalari va inkognito rejim <a class="header-anchor" href="#_1-topshiriq-brauzer-tezkor-tugmalari-va-inkognito-rejim" aria-label="Permalink to &quot;1-topshiriq. Brauzer tezkor tugmalari va inkognito rejim&quot;">​</a></h3><p><strong>Vazifa:</strong> Brauzerni oching, 3 ta yangi tab hosil qiling, ulardan birini yoping va qayta tiklang. So&#39;ngra inkognito rejimiga o&#39;ting. <strong>Yechim:</strong></p><ul><li>Brauzerda yangi tab ochish uchun <code>Ctrl + T</code> tugmasi 3 marta bosiladi.</li><li>Tabni yopish uchun <code>Ctrl + W</code> bosiladi.</li><li>Tasodifan yopilgan tabni qayta ochish uchun <code>Ctrl + Shift + T</code> bosiladi.</li><li>Maxfiy/inkognito oynasini ochish uchun <code>Ctrl + Shift + N</code> (yoki Firefox&#39;da <code>Ctrl + Shift + P</code>) bosiladi.</li></ul><h3 id="_2-topshiriq-google-qidiruv-operatorlaridan-foydalanish" tabindex="-1">2-topshiriq. Google qidiruv operatorlaridan foydalanish <a class="header-anchor" href="#_2-topshiriq-google-qidiruv-operatorlaridan-foydalanish" aria-label="Permalink to &quot;2-topshiriq. Google qidiruv operatorlaridan foydalanish&quot;">​</a></h3><p><strong>Vazifa:</strong> Quyidagi shartlar bo&#39;yicha Google qidiruviga to&#39;g&#39;ri so&#39;rov tuzing:</p><ol><li>O&#39;zbekistondagi ta&#39;lim saytlaridan (<code>.edu.uz</code>) faqat <code>dasturlash</code> mavzusini toping.</li><li>«Sun&#39;iy intellekt asoslari» nomli faqat PDF kitoblarni toping.</li><li>«Python» so&#39;zini qidirganda ilon haqidagi ma&#39;lumotlar chiqmasin. <strong>Yechim:</strong></li><li><code>dasturlash site:edu.uz</code></li><li><code>&quot;Sun&#39;iy intellekt asoslari&quot; filetype:pdf</code></li><li><code>Python -ilon -snake</code></li></ol><h3 id="_3-topshiriq-to-g-ri-elektron-xat-loyihasini-tayyorlash" tabindex="-1">3-topshiriq. To&#39;g&#39;ri elektron xat loyihasini tayyorlash <a class="header-anchor" href="#_3-topshiriq-to-g-ri-elektron-xat-loyihasini-tayyorlash" aria-label="Permalink to &quot;3-topshiriq. To&#39;g&#39;ri elektron xat loyihasini tayyorlash&quot;">​</a></h3><p><strong>Vazifa:</strong> Mentorga uy vazifasini yuborish bo&#39;yicha xat tayyorlang. Qoidalar:</p><ul><li>Asosiy qabul qiluvchi: <code>mentor@maktab.uz</code></li><li>Yashirin nusxa (Bcc): o&#39;zingizning zaxira pochtangiz</li><li>Mavzu (Subject): «8-sinf CS 2-hafta uy vazifasi - [Ismingiz]»</li><li>Xat matnida salomlashish, vazifa nima haqida ekanligi va fayl biriktirilganligi yozilsin. <strong>Yechim:</strong></li><li><strong>To:</strong> <code>mentor@maktab.uz</code></li><li><strong>Bcc:</strong> <code>shaxsiy_zaxira@gmail.com</code></li><li><strong>Subject:</strong> <code>8-sinf CS 2-hafta uy vazifasi - Sherzod Alimov</code></li><li><strong>Body:</strong><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes light-plus dark-plus vp-code" tabindex="0"><code><span class="line"><span>Assalomu alaykum, hurmatli ustoz!</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Men 8-sinf o&#39;quvchisi Sherzod Alimovman. Ushbu xatga 2-hafta bo&#39;yicha tayyorlangan amaliy uy vazifasi hujjatini biriktirdim.</span></span>
<span class="line"><span>Iltimos, tekshirib o&#39;z xulosangizni bersangiz.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Hurmat bilan,</span></span>
<span class="line"><span>Sherzod Alimov.</span></span></code></pre></div></li><li><strong>Biriktirish:</strong> Pastdagi qisqich (paperclip) belgisini bosib, fayl tanlanadi va <code>Send</code> (Yuborish) bosiladi.</li></ul><hr>`,10))]),i("div",k,[i("h2",p,[l(r,{name:"file-text"}),a[9]||(a[9]=o(" 4. Tezkor nazorat savollari (javoblari bilan) ",-1)),a[10]||(a[10]=i("a",{class:"header-anchor",href:"#_4-tezkor-nazorat-savollari-javoblari-bilan","aria-label":'Permalink to "<Icon name="file-text" /> 4. Tezkor nazorat savollari (javoblari bilan)"'},"​",-1))]),a[11]||(a[11]=t("<ol><li><strong>Savol:</strong> Internet bilan World Wide Web (WWW) ning farqi nimada? <strong>Javob:</strong> Internet — bu butun dunyodagi kompyuterlarni bog&#39;lovchi global apparat/tarmoq infratuzilmasi. WWW esa internet ustida ishlovchi, veb-saytlar va gipermatnli sahifalar tizimidir.</li><li><strong>Savol:</strong> Brauzerdagi Kesh (Cache) va Kuki (Cookies) nima vazifani bajaradi? <strong>Javob:</strong> Kesh sayt tezroq ochilishi uchun sahifa qismlarini (rasmlar, stillar) xotirada saqlaydi. Kuki esa sayt sozlamalari, foydalanuvchi ma&#39;lumotlari va tizimga kirish holatini eslab qoladi.</li><li><strong>Savol:</strong> Google&#39;da faqat PDF formatidagi ma&#39;lumotlarni qidirish uchun qaysi operator ishlatiladi? <strong>Javob:</strong> <code>filetype:pdf</code> operatori ishlatiladi.</li><li><strong>Savol:</strong> Elektron pochtada <code>Cc</code> va <code>Bcc</code> maydonlarining farqi nimada? <strong>Javob:</strong> <code>Cc</code> (nusxa) barcha qabul qiluvchilarga ko&#39;rinadi. <code>Bcc</code> (yashirin nusxa) dagi manzillarni asosiy qabul qiluvchilar ko&#39;ra olmaydi.</li><li><strong>Savol:</strong> Fishing (phishing) xati qanday xavf tug&#39;diradi? <strong>Javob:</strong> Fishing xatlari foydalanuvchini aldab soxta saytga kiritadi va uning login, parol yoki bank karta ma&#39;lumotlarini o&#39;g&#39;irlashga harakat qiladi.</li></ol>",1))])])}const C=n(h,[["render",v]]);export{W as __pageData,C as default};
